// Extract incoming fields & Session ID for 100% Hands-Free Siri Loop
const body = $input.item.json.body || $input.item.json;
const headers = $input.item.json.headers || {};

const sessionId = body.session_id || headers['x-session-id'] || 'default-session';
const textInput = body.text_input || '';
const binaryData = $input.item.binary ? $input.item.binary.audio_file : null;

// Check workflow static data for existing suspended context
const staticData = $getWorkflowStaticData('global');
const existingContext = staticData[sessionId] || null;

let combinedTextPrompt = textInput;
if (existingContext && existingContext.pendingPrompt) {
  combinedTextPrompt = `Previous Question: "${existingContext.pendingPrompt}"\nUser Follow-up Answer: "${textInput}"`;
}

const localTimeStr = new Date().toLocaleString('en-US', { timeZone: 'America/Chicago', dateStyle: 'full', timeStyle: 'full' });

return {
  json: {
    session_id: sessionId,
    text_input: combinedTextPrompt,
    raw_input: textInput,
    has_audio: !!binaryData,
    has_existing_context: !!existingContext,
    user_local_time: localTimeStr
  },
  binary: binaryData ? { audio_file: binaryData } : {}
};

