// Parse Gemini Response JSON for Siri Voice Output
const responseText = $input.item.json.candidates[0].content.parts[0].text;
let parsed;
try {
  parsed = JSON.parse(responseText);
} catch (e) {
  parsed = {
    status: 'AMBIGUOUS',
    clarification_prompt: 'I could not understand your request. Could you please rephrase?',
    intent: 'AMBIGUOUS',
    parameters: {}
  };
}

const sessionId = $('Prepare Input & Context').item.json.session_id;
const staticData = $getWorkflowStaticData('global');

if (parsed.status === 'NEEDS_CLARIFICATION') {
  // Store state in static data for Clarification Loop
  staticData[sessionId] = {
    pendingPrompt: parsed.clarification_prompt,
    updatedAt: new Date().toISOString()
  };
} else {
  // Clear state on READY
  if (staticData[sessionId]) {
    delete staticData[sessionId];
  }
}

return {
  json: {
    session_id: sessionId,
    status: parsed.status,
    clarification_prompt: parsed.clarification_prompt,
    intent: parsed.intent,
    parameters: parsed.parameters || {}
  }
};

